use achimeld_browser::snapshot::{self, FIXTURE_REVISION};
use achimeld_core::{
    Decimal, SteamAppId,
    canonical::{self, Value},
};
use serde_json::Value as Json;

// Expected hashes are generated by compiling the real legacy reader and fingerprint code.
// No .NET runtime is required to run these committed regression tests.
#[test]
fn rust_snapshots_match_the_actual_csharp_reader() {
    let golden: Json = serde_json::from_str(include_str!(
        "../../../tests/fixtures/steamworks/legacy-golden.json"
    ))
    .unwrap();
    let fixture = include_str!("../../../tests/fixtures/steamworks/normalized-2026-09.html");
    for expected in golden["snapshots"].as_array().unwrap() {
        let html = fixture.replace(FIXTURE_REVISION, expected["revision"].as_str().unwrap());
        let actual = snapshot::parse(&html, SteamAppId::new(480).unwrap()).unwrap();
        assert_eq!(
            actual.content_fingerprint,
            expected["fingerprint"].as_str().unwrap()
        );
        for (key, hashes) in [
            (
                "stats",
                actual
                    .stats
                    .iter()
                    .map(|e| e.content_fingerprint.clone())
                    .collect::<Vec<_>>(),
            ),
            (
                "achievements",
                actual
                    .achievements
                    .iter()
                    .map(|e| e.content_fingerprint.clone())
                    .collect(),
            ),
            (
                "localizations",
                actual
                    .localizations
                    .iter()
                    .map(|e| e.content_fingerprint.clone())
                    .collect(),
            ),
            (
                "icons",
                actual
                    .icons
                    .iter()
                    .map(|e| e.content_fingerprint.clone())
                    .collect(),
            ),
        ] {
            assert_eq!(
                serde_json::to_value(hashes).unwrap(),
                expected[key],
                "{key}"
            );
        }
    }
}
#[test]
fn decimal_and_unicode_hashes_match_dotnet() {
    let golden: Json = serde_json::from_str(include_str!(
        "../../../tests/fixtures/steamworks/legacy-golden.json"
    ))
    .unwrap();
    for expected in golden["decimals"].as_array().unwrap() {
        let number = Decimal::from_str_exact(expected["input"].as_str().unwrap()).unwrap();
        assert_eq!(
            canonical::decimal_g29(number),
            expected["encoded"].as_str().unwrap()
        );
        assert_eq!(
            canonical::value_hash(&Value::Decimal(number)),
            expected["fingerprint"].as_str().unwrap()
        );
    }
    let unicode = canonical::compute(vec![
        ("😀".into(), Value::Text("e\u{301}\r\n😀".into())),
        (
            "\u{e000}".into(),
            Value::Strings(vec!["é".into(), "line\rbreak".into()]),
        ),
    ])
    .unwrap();
    assert_eq!(
        unicode.entity,
        golden["unicodeFingerprint"].as_str().unwrap()
    );
}

#[test]
fn configuration_request_frame_matches_the_csharp_wire() {
    use achimeld_browser::protocol::WorkerRequest;
    let golden: Json = serde_json::from_str(include_str!(
        "../../../tests/fixtures/steamworks/legacy-golden.json"
    ))
    .unwrap();
    let legacy = hex::decode(golden["workerReadRequestFrameHex"].as_str().unwrap()).unwrap();
    let request: WorkerRequest =
        achimeld_security::wire::read_frame(&mut legacy.as_slice(), 32 * 1024 * 1024).unwrap();
    assert_eq!(request.operation, "readConfiguration");
    let app_id: SteamAppId = serde_json::from_value(request.arguments.clone()).unwrap();
    assert_eq!(app_id.value(), 480);
    let mut rust = Vec::new();
    achimeld_security::wire::write_frame(&mut rust, &request, 32 * 1024 * 1024).unwrap();
    assert_eq!(rust, legacy);
}
